/** Regroupe par département (DOM, Monaco, Israël puis « Autre » en fin de liste). */
export function groupByRegion(list: Officiant[]) {
  const map: Record<string, Officiant[]> = {};
  for (const o of list) {
    for (const v of o.villes) {
      if (!map[v.region]) map[v.region] = [];
      if (!map[v.region].some((x) => x.id === o.id)) map[v.region].push(o);
    }
  }
  return Object.entries(map).sort(([a], [b]) => rank(a) - rank(b) || a.localeCompare(b, 'fr'));
}

function rank(region: string) {
  if (region === 'Israël') return 1000;
  if (region === 'Autre / non précisé') return 1001;
  if (region === 'Monaco') return 998;
  const m = region.match(/\(([0-9AB]+)\)/);
  if (!m) return 999;
  if (m[1] === '2A') return 20;
  if (m[1] === '2B') return 20.5;
  return Number(m[1]);
}
